cat > tests/selection.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert';
import { canAdd } from '../src/lib/selection.ts';

const L = { portrait: false };
const P = { portrait: true };

test('landscape cap is 2', () => {
  assert.ok(canAdd([], L));
  assert.ok(canAdd([L], L));
  assert.ok(!canAdd([L, L], L));
});

test('portrait cap is 1', () => {
  assert.ok(canAdd([], P));
  assert.ok(!canAdd([P], P));
});

test('caps are independent', () => {
  assert.ok(canAdd([L, L], P));
  assert.ok(canAdd([P], L));
});
EOF
node --experimental-strip-types --test tests/ 2>&1 | grep -E "^# (pass|fail)|not ok"

